-- PostgreSQL baseline corresponding to MySQL migrations through Version20261012070000.
CREATE TABLE account_security (user_id UUID  NOT NULL, secret TEXT  DEFAULT NULL, pending_secret TEXT  DEFAULT NULL, pending_until BIGINT DEFAULT 0 NOT NULL, last_step BIGINT DEFAULT -1 NOT NULL, recovery_hashes JSONB NOT NULL, version INT DEFAULT 0 NOT NULL, recovery_until BIGINT DEFAULT 0 NOT NULL, PRIMARY KEY (user_id));
