CREATE TABLE forms_records (id UUID  NOT NULL, kind VARCHAR(40)  NOT NULL, payload JSONB NOT NULL, version INT NOT NULL, form_id UUID  DEFAULT NULL, public_token CHAR(64)  DEFAULT NULL, submission_key UUID  DEFAULT NULL, PRIMARY KEY (id));
